function (settings, time, ctx) {
  // ---------- SETTINGS ----------
  var LABEL        = settings.label.value;            // small caption top-left ('' = none)
  var UNIT         = settings.unit.value;             // unit text after the value ('' = none)
  var MULTIPLIER   = settings.multiplier.value;       // value * multiplier (1 = as is; rssi 0..1023 -> % = 0.0977, m/s -> km/h = 3.6)
  var DIGITS       = settings.digits.value;           // decimal places of the value
  var MIN          = settings.min.value;              // value (after the multiplier) at which no bar is lit
  var MAX          = settings.max.value;              // value (after the multiplier) at which every bar is lit
  var SMOOTH_MS    = settings.smooth_ms.value;        // moving average window for the value in ms (0 = off)
  var COUNT        = settings.bars.value;             // number of bars
  var FILL_MODE    = settings.fill.value;             // 'steps' = whole bars only | 'smooth' = the last lit bar fills gradually
  var FIRST_PCT    = settings.first_bar_height.value; // height of the first (lowest) bar in % of the last one (100 = all equal)
  var GAP          = settings.gap.value;              // space between bars at the default 240x140 size; scales with the widget
  var BAR_RADIUS   = settings.bar_radius.value;       // corner radius of the bars at the default size; scales with the widget
  var TRACK_COLOR  = settings.track_color.value;      // unlit bars
  var FILL_COLOR   = settings.fill_color.value;       // lit bars below Limit 1
  var LIMIT_1      = settings.limit_1.value;          // from this value (after the multiplier) the lit bars use Color 1
  var COLOR_1      = settings.color_1.value;          // lit bars from Limit 1 up
  var LIMIT_2      = settings.limit_2.value;          // from this value the lit bars use Color 2
  var COLOR_2      = settings.color_2.value;          // lit bars from Limit 2 up
  var LIMIT_3      = settings.limit_3.value;          // from this value the lit bars use Color 3
  var COLOR_3      = settings.color_3.value;          // lit bars from Limit 3 up
  var BLEND        = settings.blend.value;            // fade smoothly from one color to the next around each limit instead of switching at once
  var BLEND_SPAN   = settings.blend_span.value;       // length of the fade in value units (after the multiplier), centred on the limit
  var LABEL_COLOR  = settings.label_color.value;      // caption color
  var LABEL_SIZE   = settings.label_size.value;       // caption font size at the default 240x140 size; scales with the widget
  var VALUE_COLOR  = settings.value_color.value;      // value color
  var VALUE_SIZE   = settings.value_size.value;       // value font size at the default size; scales with the widget
  var UNIT_COLOR   = settings.unit_color.value;       // unit color
  var UNIT_SIZE    = settings.unit_size.value;        // unit font size at the default size; scales with the widget
  var FONT         = settings.font.value;             // font family
  var SHADOW       = settings.text_shadow.value;      // CSS text shadow for all texts ('' = none)
  var BG           = settings.background.value;       // box background; alpha 0 = no box
  var RADIUS       = settings.radius.value;           // box corner radius at the default size; scales with the widget
  var PADDING      = settings.padding.value;          // inner padding at the default size; scales with the widget
  var OPACITY      = settings.opacity.value;          // whole-widget opacity 0..1 (1 = opaque)
  // -------------------------------
  var W = ctx.width, H = ctx.height, s = ctx.state, i;
  var scale = Math.min(W / 240, H / 140);
  var col = ctx.columns[0];

  // ---- value (smoothed when asked; only inside the telemetry range) ----
  var raw = ctx.values[0], cur;
  if (typeof raw === 'number') {
    if (SMOOTH_MS > 0 && col) {
      var sam = ctx.range(col, time - SMOOTH_MS / 2, time + SMOOTH_MS / 2, 400) || [], sum = 0, cnt = 0;
      for (i = 0; i < sam.length; i++) if (typeof sam[i].v === 'number') { sum += sam[i].v; cnt++; }
      cur = cnt ? sum / cnt : raw;
    } else cur = raw;
    cur *= MULTIPLIER;
  }
  var mn = MIN, mx = MAX; if (!(mx > mn)) mx = mn + 1;
  var n = Math.max(1, Math.min(50, Math.round(COUNT)));

  // ---- colour of the lit bars: the highest limit the value has reached wins; with Blend the colours cross-fade around each limit ----
  function rgba(c) {                                  // CSS colour -> [r, g, b, a] or null (named colours are not parsed)
    var m; c = String(c).trim();
    if ((m = /^#([0-9a-f]{3,4})$/i.exec(c))) { var h = m[1]; return [parseInt(h[0] + h[0], 16), parseInt(h[1] + h[1], 16), parseInt(h[2] + h[2], 16), h.length > 3 ? parseInt(h[3] + h[3], 16) / 255 : 1]; }
    if ((m = /^#([0-9a-f]{6}|[0-9a-f]{8})$/i.exec(c))) { var x = m[1]; return [parseInt(x.slice(0, 2), 16), parseInt(x.slice(2, 4), 16), parseInt(x.slice(4, 6), 16), x.length > 6 ? parseInt(x.slice(6, 8), 16) / 255 : 1]; }
    if ((m = /^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)\s*(?:,\s*([\d.]+)\s*)?\)$/i.exec(c))) return [+m[1], +m[2], +m[3], m[4] === undefined ? 1 : +m[4]];
    return null;
  }
  function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t, a[3] + (b[3] - a[3]) * t]; }
  var color = FILL_COLOR;
  if (typeof cur === 'number') {
    var lims = [[LIMIT_1, COLOR_1], [LIMIT_2, COLOR_2], [LIMIT_3, COLOR_3]], k, span = BLEND_SPAN;
    var c0 = BLEND && span > 0 ? rgba(FILL_COLOR) : null;
    if (c0) {
      for (k = 0; k < 3; k++) {                       // fade from the previous colour into Color k over limit - span/2 .. limit + span/2
        var ck = rgba(lims[k][1]); if (!ck) { c0 = null; break; }
        var t = Math.max(0, Math.min(1, (cur - (lims[k][0] - span / 2)) / span));
        c0 = mix(c0, ck, t);
      }
    }
    if (c0) color = 'rgba(' + Math.round(c0[0]) + ',' + Math.round(c0[1]) + ',' + Math.round(c0[2]) + ',' + c0[3].toFixed(3) + ')';
    else for (k = 0; k < 3; k++) if (cur >= lims[k][0]) color = lims[k][1];
  }

  // ---- layout: caption + value row on top, bars below, aligned to the bottom ----
  var p = PADDING * scale, lfs = LABEL_SIZE * scale, fs = VALUE_SIZE * scale, ufs = UNIT_SIZE * scale;
  var rowH = Math.max(LABEL ? lfs * 1.25 : 0, fs * 1.15);
  var top = p + rowH + 4 * scale, bottom = H - p;
  var areaH = Math.max(4 * scale, bottom - top), areaW = W - 2 * p;
  var gap = GAP * scale, bw = Math.max(1, (areaW - gap * (n - 1)) / n);
  var rx = Math.min(BAR_RADIUS * scale, bw / 2, areaH / 2);
  var first = Math.max(2, Math.min(100, FIRST_PCT)) / 100;
  var frac = typeof cur === 'number' ? Math.max(0, Math.min(1, (cur - mn) / (mx - mn))) : 0;
  var lit = frac * n;                                   // bars lit, fractional
  var uid = (s.uid || (s.uid = 'u' + Math.random().toString(36).slice(2, 8))) + (s.frame = ((s.frame || 0) + 1) % 1000000);

  var out = '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" style="display:block;font-family:' + FONT + ';opacity:' + OPACITY
    + ';background:' + BG + ';border-radius:' + (RADIUS * scale).toFixed(1) + 'px">';
  for (i = 0; i < n; i++) {
    var bh = n === 1 ? areaH : areaH * (first + (1 - first) * i / (n - 1));
    var x = p + i * (bw + gap), y = bottom - bh;
    var rect = ' x="' + x.toFixed(2) + '" y="' + y.toFixed(2) + '" width="' + bw.toFixed(2) + '" height="' + bh.toFixed(2) + '" rx="' + rx.toFixed(2) + '"';
    var f = lit - i;                                    // >= 1 fully lit, <= 0 unlit, between = partial (smooth mode)
    if (f >= 0.999 || (FILL_MODE === 'steps' && f >= 0.5)) out += '<rect' + rect + ' fill="' + color + '"/>';
    else if (FILL_MODE === 'smooth' && f > 0.001) {
      // partial bar: the unlit shape plus the fill clipped by the bar shape grown 1 px, so the track's light edge does not halo the fill
      var g = 1 * scale, fh = bh * f;
      out += '<rect' + rect + ' fill="' + TRACK_COLOR + '"/>'
        + '<clipPath id="' + uid + 'b' + i + '"><rect x="' + (x - g).toFixed(2) + '" y="' + (y - g).toFixed(2) + '" width="' + (bw + 2 * g).toFixed(2) + '" height="' + (bh + 2 * g).toFixed(2) + '" rx="' + (rx + g).toFixed(2) + '"/></clipPath>'
        + '<rect x="' + (x - g).toFixed(2) + '" y="' + (bottom - fh).toFixed(2) + '" width="' + (bw + 2 * g).toFixed(2) + '" height="' + (fh + g).toFixed(2) + '" fill="' + color + '" clip-path="url(#' + uid + 'b' + i + ')"/>';
    }
    else out += '<rect' + rect + ' fill="' + TRACK_COLOR + '"/>';
  }
  // ---- texts: caption top-left, value (+ unit) top-right ----
  var shadow = SHADOW ? ' style="text-shadow:' + SHADOW + '"' : '';
  var ry = p + rowH / 2;
  if (LABEL) out += '<text x="' + p.toFixed(2) + '" y="' + ry.toFixed(2) + '" fill="' + LABEL_COLOR + '" font-size="' + lfs.toFixed(1) + '" font-weight="bold" letter-spacing="' + (1 * scale).toFixed(1) + '" dominant-baseline="central"' + shadow + '>' + LABEL + '</text>';
  out += '<text x="' + (W - p).toFixed(2) + '" y="' + ry.toFixed(2) + '" fill="' + VALUE_COLOR + '" font-size="' + fs.toFixed(1) + '" font-weight="bold" text-anchor="end" dominant-baseline="central"' + shadow + '>'
    + (typeof cur === 'number' ? cur.toFixed(DIGITS) : '--')
    + (UNIT ? '<tspan fill="' + UNIT_COLOR + '" font-size="' + ufs.toFixed(1) + '" font-weight="normal" dx="' + (fs * 0.12).toFixed(1) + '">' + UNIT + '</tspan>' : '')
    + '</text>';
  out += '</svg>';
  return out;
}
